IF OBJECT_ID('dbWMS.dbo.InboundPlans','U') IS NULL CREATE TABLE dbWMS.dbo.InboundPlans(PlanId int IDENTITY PRIMARY KEY,RequestId uniqueidentifier NOT NULL UNIQUE,WhId int NOT NULL,CategoryCode varchar(4) NOT NULL,ArrivalDate date NOT NULL,Payload nvarchar(max) NOT NULL CHECK(ISJSON(Payload)=1),CreatedBy nvarchar(100) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSDATETIME());